export function getMLMLAProfile(acNo: number): MLAProfile | undefined {
  return ML_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getMLMLAsByParty(party: string): MLAProfile[] {
  return ML_MLA_PROFILES.filter(p => p.party === party);
}

export function getMLFemaleMLAs(): MLAProfile[] {
  return ML_MLA_PROFILES.filter(p => p.gender === 'F');
}
